```cpp
#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    const std::size_t n = points.size();

#pragma omp parallel
    {
        std::array<std::size_t, 4> local = {0, 0, 0, 0};

#pragma omp for nowait
        for (std::size_t i = 0; i < n; ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Treat points on axes as belonging to the "positive" side for that axis:
            // x >= 0 and/or y >= 0.
            if (x >= 0.0) {
                if (y >= 0.0) {
                    ++local[0]; // Quadrant I
                } else {
                    ++local[3]; // Quadrant IV
                }
            } else {
                if (y >= 0.0) {
                    ++local[1]; // Quadrant II
                } else {
                    ++local[2]; // Quadrant III
                }
            }
        }

#pragma omp critical
        {
            bins[0] += local[0];
            bins[1] += local[1];
            bins[2] += local[2];
            bins[3] += local[3];
        }
    }
}
